arguments.file_text:
@using sv_39c53aaf22e646a6b869ba2fcec77a7a.Models

<div class="profile-section">
    <h4>Profile Settings</h4>

    @if (statusMessage is not null)
    {
        <div class="alert @(isError ? "alert-danger" : "alert-success") alert-dismissible fade show" role="alert">
            @statusMessage
            <button type="button" class="btn-close" @onclick="() => statusMessage = null"></button>
        </div>
    }

    <div class="avatar-area mb-4">
        <div class="avatar-preview">
            @if (!string.IsNullOrWhiteSpace(avatarUrl))
            {
                <img src="@avatarUrl" alt="Avatar" class="avatar-image" />
            }
            else
            {
                <div class="avatar-placeholder">👤</div>
            }
        </div>
        <div class="avatar-url-display">
            <label class="form-label">Avatar URL</label>
            <input type="url" class="form-control" value="@avatarUrl" disabled />
        </div>
    </div>

    <div class="mb-3">
        <label class="form-label">Display Name</label>
        <input type="text" class="form-control" @bind="displayName" />
    </div>

    <div class="mb-3">
        <label class="form-label">Email</label>
        <input type="email" class="form-control" @bind="email" />
    </div>

    <div class="mb-3">
        <label class="form-label">Bio</label>
        <textarea class="form-control" rows="4" @bind="bio"></textarea>
    </div>

    <div class="d-flex gap-2">
        <button class="btn btn-primary" @onclick="SaveAsync" disabled="@saving">
            @if (saving) { <span class="spinner-border spinner-border-sm me-1"></span> }
            Save Changes
        </button>
        <button class="btn btn-outline-secondary" @onclick="Discard" disabled="@saving">
            Discard Changes
        </button>
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public UserProfile Profile { get; set; } = default!;

    [Parameter, EditorRequired]
    public EventCallback<UserProfile> OnSave { get; set; }

    private string displayName = "";
    private string email = "";
    private string avatarUrl = "";
    private string bio = "";
    private string? statusMessage;
    private bool isError;
    private bool saving;

    protected override void OnParametersSet()
    {
        if (!hasLocalEdits)
        {
            LoadFromProfile();
        }
    }

    private bool hasLocalEdits;

    private void LoadFromProfile()
    {
        displayName = Profile.DisplayName;
        email = Profile.Email;
        avatarUrl = Profile.AvatarUrl;
        bio = Profile.Bio;
        hasLocalEdits = false;
    }

    private async Task SaveAsync()
    {
        saving = true;
        statusMessage = null;
        try
        {
            var updated = new UserProfile(displayName, email, avatarUrl, bio);
            await OnSave.InvokeAsync(updated);
            hasLocalEdits = false;
            statusMessage = "Profile saved successfully!";
            isError = false;
        }
        catch
        {
            statusMessage = "Failed to save profile. Please try again.";
            isError = true;
        }
        finally
        {
            saving = false;
        }
    }

    private void Discard()
    {
        LoadFromProfile();
        statusMessage = null;
    }
}

.profile-section {
    max-width: 600px;
}

.avatar-area {
    display: flex;
    align-items: flex-start;
    gap: 1.5rem;
}

.avatar-preview {
    flex-shrink: 0;
    width: 80px;
    height: 80px;
    border-radius: 50%;
    overflow: hidden;
    border: 2px solid #dee2e6;
    display: flex;
    align-items: center;
    justify-content: center;
    background-color: #f8f9fa;
}

.avatar-image {
    width: 100%;
    height: 100%;
    object-fit: cover;
}

.avatar-placeholder {
    font-size: 2rem;
}

.avatar-url-display {
    flex: 1;
    min-width: 0;
}

@using sv_39c53aaf22e646a6b869ba2fcec77a7a.Models

<div class="notifications-section">
    <h4>Notification Preferences</h4>

    @if (statusMessage is not null)
    {
        <div class="alert @(isError ? "alert-danger" : "alert-success") alert-dismissible fade show" role="alert">
            @statusMessage
            <button type="button" class="btn-close" @onclick="() => statusMessage = null"></button>
        </div>
    }

    <div class="card mb-4">
        <div class="card-body">
            <h6 class="card-title">General</h6>

            <div class="form-check form-switch mb-3">
                <input class="form-check-input" type="checkbox" id="emailNotif" @bind="emailNotifications" />
                <label class="form-check-label" for="emailNotif">Email Notifications</label>
                <div class="form-text">Receive notifications via email</div>
            </div>

            <div class="form-check form-switch mb-3">
                <input class="form-check-input" type="checkbox" id="pushNotif" @bind="pushNotifications" />
                <label class="form-check-label" for="pushNotif">Push Notifications</label>
                <div class="form-text">Receive push notifications in your browser</div>
            </div>

            <div class="form-check form-switch">
                <input class="form-check-input" type="checkbox" id="weeklyDigest" @bind="weeklyDigest" />
                <label class="form-check-label" for="weeklyDigest">Weekly Digest</label>
                <div class="form-text">Receive a weekly summary email</div>
            </div>
        </div>
    </div>

    <div class="card mb-4">
        <div class="card-body">
            <h6 class="card-title">Muted Channels</h6>
            <p class="text-muted small">Select channels to mute notifications from.</p>

            @foreach (var channel in AvailableChannels)
            {
                <div class="form-check mb-2">
                    <input class="form-check-input"
                           type="checkbox"
                           id="@($"ch-{channel}")"
                           checked="@mutedChannels.Contains(channel)"
                           @onchange="e => ToggleMute(channel, (bool)e.Value!)" />
                    <label class="form-check-label" for="@($"ch-{channel}")">@channel</label>
                </div>
            }
        </div>
    </div>

    <button class="btn btn-primary" @onclick="SaveAsync" disabled="@saving">
        @if (saving) { <span class="spinner-border spinner-border-sm me-1"></span> }
        Save Preferences
    </button>
</div>

