            {
                <div class="form-check mb-2">
                    <input class="form-check-input"
                           type="checkbox"
                           id="@($"ch-{channel}")"
                           checked="@mutedChannels.Contains(channel)"
                           @onchange="e => ToggleMute(channel, (bool)e.Value!)" />
                    <label class="form-check-label" for="@($"ch-{channel}")">@channel</label>
                </div>
            }
        </div>
    </div>

    <button class="btn btn-primary" @onclick="SaveAsync" disabled="@saving">
        @if (saving) { <span class="spinner-border spinner-border-sm me-1"></span> }
        Save Preferences
    </button>
</div>

@code {
    [Parameter, EditorRequired]
    public NotificationPrefs Prefs { get; set; } = default!;

    [Parameter, EditorRequired]
    public EventCallback<NotificationPrefs> OnSave { get; set; }

    [Parameter]
    public List<string> AvailableChannels { get; set; } = ["General", "Announcements", "Engineering", "Marketing", "Support", "Random"];

    private bool emailNotifications;
    private bool pushNotifications;
    private bool weeklyDigest;
    private HashSet<string> mutedChannels = [];
    private string? statusMessage;
    private bool isError;
    private bool saving;
    private bool initialized;

    protected override void OnParametersSet()
    {
        if (!initialized)
        {
            emailNotifications = Prefs.EmailNotifications;
            pushNotifications = Prefs.PushNotifications;
            weeklyDigest = Prefs.WeeklyDigest;
            mutedChannels = [.. Prefs.MutedChannels];
            initialized = true;
        }
    }

    private void ToggleMute(string channel, bool isMuted)
    {
        if (isMuted)
            mutedChannels.Add(channel);
        else
            mutedChannels.Remove(channel);
    }

    private async Task SaveAsync()
    {
        saving = true;
        statusMessage = null;
        try
        {
            var updated = new NotificationPrefs(emailNotifications, pushNotifications, weeklyDigest, [.. mutedChannels]);
            await OnSave.InvokeAsync(updated);
            statusMessage = "Notification preferences saved!";
            isError = false;
        }
        catch
        {
            statusMessage = "Failed to save preferences. Please try again.";
            isError = true;
        }
        finally
        {
            saving = false;
        }
    }
}

