arguments.file_text:
@using sv_39c53aaf22e646a6b869ba2fcec77a7a.Models

<div class="security-section">
    <h4>Security Settings</h4>

    @if (statusMessage is not null)
    {
        <div class="alert @(isError ? "alert-danger" : "alert-success") alert-dismissible fade show" role="alert">
            @statusMessage
            <button type="button" class="btn-close" @onclick="() => statusMessage = null"></button>
        </div>
    }

    @* Change Password Panel *@
    <div class="card mb-4">
        <div class="card-header d-flex justify-content-between align-items-center"
             style="cursor: pointer"
             @onclick="() => passwordPanelOpen = !passwordPanelOpen">
            <span>🔑 Change Password</span>
            <span>@(passwordPanelOpen ? "▲" : "▼")</span>
        </div>
        @if (passwordPanelOpen)
        {
            <div class="card-body">
                <div class="mb-3">
                    <label class="form-label">Current Password</label>
                    <input type="password" class="form-control" @bind="currentPassword" />
                </div>
                <div class="mb-3">
                    <label class="form-label">New Password</label>
                    <input type="password" class="form-control" @bind="newPassword" />
                </div>
                <div class="mb-3">
                    <label class="form-label">Confirm New Password</label>
                    <input type="password" class="form-control" @bind="confirmPassword" />
                </div>
                @if (passwordError is not null)
                {
                    <div class="text-danger mb-2">@passwordError</div>
                }
                <button class="btn btn-warning" @onclick="ChangePasswordAsync" disabled="@changingPassword">
                    @if (changingPassword) { <span class="spinner-border spinner-border-sm me-1"></span> }
                    Update Password
                </button>
                @if (Settings.LastPasswordChange.HasValue)
                {
                    <div class="text-muted small mt-2">
                        Last changed: @Settings.LastPasswordChange.Value.ToString("MMMM dd, yyyy")
                    </div>
                }
            </div>
        }
    </div>

    @* Two-Factor Authentication *@
    <div class="card mb-4">
        <div class="card-body d-flex justify-content-between align-items-center">
            <div>
                <h6 class="mb-1">Two-Factor Authentication</h6>
                <span class="badge @(Settings.TwoFactorEnabled ? "bg-success" : "bg-secondary")">
                    @(Settings.TwoFactorEnabled ? "Enabled" : "Disabled")
                </span>
            </div>
            <div class="form-check form-switch">
                <input class="form-check-input" type="checkbox"
                       checked="@Settings.TwoFactorEnabled" disabled
                       style="transform: scale(1.3);" />
            </div>
        </div>
    </div>

    @* Active Sessions *@
    <div class="card mb-4">
        <div class="card-header">
            <h6 class="mb-0">Active Sessions</h6>
        </div>
        <div class="card-body p-0">
            <div class="table-responsive">
                <table class="table table-hover mb-0">
                    <thead>
                        <tr>
                            <th>Device</th>
                            <th>Location</th>
                            <th>Last Active</th>
                            <th></th>
                        </tr>
                    </thead>
                    <tbody>
                        @foreach (var session in Settings.Sessions)
                        {
                            <tr>
                                <td>@session.Device</td>
                                <td>@session.Location</td>
                                <td>@session.LastActive.ToString("MMM dd, yyyy h:mm tt")</td>
                                <td>
                                    @if (session.Id != CurrentSessionId)
                                    {
                                        <button class="btn btn-sm btn-outline-danger"
                                                @onclick="() => PromptRevoke(session)">
                                            Revoke
                                        </button>
                                    }
                                    else
                                    {
                                        <span class="badge bg-info">Current</span>
                                    }
                                </td>
                            </tr>
                        }
                    </tbody>
                </table>
            </div>
        </div>
    </div>

    @* Revoke Confirmation Dialog *@
    @if (sessionToRevoke is not null)
    {
        <div class="modal-backdrop fade show"></div>
        <div class="modal fade show d-block" tabindex="-1" role="dialog">
            <div class="modal-dialog modal-dialog-centered">
                <div class="modal-content">
                    <div class="modal-header">
                        <h5 class="modal-title">Revoke Session</h5>
                        <button type="button" class="btn-close" @onclick="CancelRevoke"></button>
                    </div>
                    <div class="modal-body">
                        <p>Are you sure you want to revoke the session for <strong>@sessionToRevoke.Device</strong> in <strong>@sessionToRevoke.Location</strong>?</p>
                        <p class="text-muted small">This will sign the device out immediately.</p>
                    </div>
                    <div class="modal-footer">
                        <button class="btn btn-secondary" @onclick="CancelRevoke" disabled="@revoking">Cancel</button>
                        <button class="btn btn-danger" @onclick="ConfirmRevokeAsync" disabled="@revoking">
                            @if (revoking) { <span class="spinner-border spinner-border-sm me-1"></span> }
                            Revoke Session
                        </button>
                    </div>
                </div>
            </div>
        </div>
    }
</div>

@code {
    [Parameter, EditorRequired]
    public SecuritySettings Settings { get; set; } = default!;

    [Parameter]
    public string? CurrentSessionId { get; set; }

    [Parameter, EditorRequired]
    public EventCallback<(string currentPassword, string newPassword)> OnChangePassword { get; set; }

    [Parameter, EditorRequired]
    public EventCallback<string> OnRevokeSession { get; set; }

    private bool passwordPanelOpen;
    private string currentPassword = "";
    private string newPassword = "";
    private string confirmPassword = "";
    private string? passwordError;
    private bool changingPassword;

    private ActiveSession? sessionToRevoke;
    private bool revoking;
    private string? statusMessage;
    private bool isError;

    private async Task ChangePasswordAsync()
    {
        passwordError = null;

        if (string.IsNullOrWhiteSpace(currentPassword) || string.IsNullOrWhiteSpace(newPassword))
        {
            passwordError = "All password fields are required.";
            return;
        }
        if (newPassword != confirmPassword)
        {
            passwordError = "New password and confirmation do not match.";
            return;
        }
        if (newPassword.Length < 8)
        {
            passwordError = "New password must be at least 8 characters.";
            return;
        }

        changingPassword = true;
        try
        {
            await OnChangePassword.InvokeAsync((currentPassword, newPassword));
            currentPassword = "";
            newPassword = "";
            confirmPassword = "";
            passwordPanelOpen = false;
            statusMessage = "Password updated successfully!";
            isError = false;
        }
        catch
        {
            statusMessage = "Failed to change password. Please try again.";
            isError = true;
        }
        finally
        {
            changingPassword = false;
        }
    }

    private void PromptRevoke(ActiveSession session)
    {
        sessionToRevoke = session;
    }

    private void CancelRevoke()
    {
        sessionToRevoke = null;
    }

    private async Task ConfirmRevokeAsync()
    {
        if (sessionToRevoke is null) return;

        revoking = true;
        try
        {
            await OnRevokeSession.InvokeAsync(sessionToRevoke.Id);
            statusMessage = $"Session on {sessionToRevoke.Device} revoked.";
            isError = false;
            sessionToRevoke = null;
        }
        catch
        {
            statusMessage = "Failed to revoke session. Please try again.";
            isError = true;
        }
        finally
        {
            revoking = false;
        }
    }
}

.security-section {
    max-width: 700px;
}

.modal-backdrop {
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    z-index: 1040;
}

.modal {
    z-index: 1050;
}

@using sv_39c53aaf22e646a6b869ba2fcec77a7a.Models

<div class="appearance-section">
    <h4>Appearance Settings</h4>

    @if (statusMessage is not null)
    {
        <div class="alert @(isError ? "alert-danger" : "alert-success") alert-dismissible fade show" role="alert">
            @statusMessage
            <button type="button" class="btn-close" @onclick="() => statusMessage = null"></button>
        </div>
    }

    <div class="row">
        <div class="col-md-6">
            @* Theme *@
            <div class="card mb-4">
                <div class="card-body">
                    <h6 class="card-title">Theme</h6>
                    @foreach (var option in new[] { "Light", "Dark", "System" })
                    {
                        <div class="form-check mb-2">
                            <input class="form-check-input" type="radio" name="theme"
                                   id="@($"theme-{option}")"
                                   value="@option"
                                   checked="@(theme == option)"
                                   @onchange="() => theme = option" />
                            <label class="form-check-label" for="@($"theme-{option}")">@option</label>
                        </div>
                    }
                </div>
            </div>

            @* Font Size *@
            <div class="card mb-4">
                <div class="card-body">
                    <h6 class="card-title">Font Size</h6>
                    @foreach (var option in new[] { "Small", "Medium", "Large" })
                    {
                        <div class="form-check mb-2">
                            <input class="form-check-input" type="radio" name="fontSize"
                                   id="@($"fs-{option}")"
                                   value="@option"
                                   checked="@(fontSize == option)"
                                   @onchange="() => fontSize = option" />
                            <label class="form-check-label" for="@($"fs-{option}")">@option</label>
                        </div>
                    }
                </div>
            </div>

            @* Language *@
            <div class="card mb-4">
                <div class="card-body">
                    <h6 class="card-title">Language</h6>
                    <select class="form-select" @bind="language">
                        <option value="en">English</option>
                        <option value="es">Español</option>
                        <option value="fr">Français</option>
                        <option value="de">Deutsch</option>
                        <option value="ja">日本語</option>
                        <option value="zh">中文</option>
                    </select>
                </div>
            </div>

            @* Compact Mode *@
            <div class="card mb-4">
                <div class="card-body">
                    <div class="form-check form-switch">
                        <input class="form-check-input" type="checkbox" id="compactMode" @bind="compactMode" />
                        <label class="form-check-label" for="compactMode">Compact Mode</label>
                        <div class="form-text">Reduce spacing and padding throughout the interface</div>
                    </div>
                </div>
            </div>

            <button class="btn btn-primary" @onclick="SaveAsync" disabled="@saving">
                @if (saving) { <span class="spinner-border spinner-border-sm me-1"></span> }
                Save
            </button>
        </div>

        @* Live Preview *@
        <div class="col-md-6">
            <div class="card">
                <div class="card-header">
                    <h6 class="mb-0">Preview</h6>
                </div>
                <div class="card-body preview-area @PreviewThemeClass"
                     style="@PreviewFontStyle @PreviewPaddingStyle">
                    <div class="preview-header mb-2" style="font-weight: 600;">
                        Dashboard
                    </div>
                    <div class="preview-nav mb-3">
                        <span class="preview-tab active">Home</span>
                        <span class="preview-tab">Settings</span>
                        <span class="preview-tab">Reports</span>
                    </div>
                    <div class="preview-card">
                        <div style="font-weight: 500;">Sample Card</div>
