{"file_text": "@using sv_39c53aaf22e646a6b869ba2fcec77a7a.Models

<div class="appearance-section">
    <h4>Appearance Settings</h4>

    @if (statusMessage is not null)
    {
        <div class="alert @(isError ? "alert-danger" : "alert-success") alert-dismissible fade show" role="alert">
            @statusMessage
            <button type="button" class="btn-close" @onclick="() => statusMessage = null"></button>
        </div>
    }

    <div class="row">
        <div class="col-md-6">
            @* Theme *@
            <div class="card mb-4">
                <div class="card-body">
                    <h6 class="card-title">Theme</h6>
                    @foreach (var option in new[] { "Light", "Dark", "System" })
                    {
                        <div class="form-check mb-2">
                            <input class="form-check-input" type="radio" name="theme"
                                   id="@($"theme-{option}")"
                                   value="@option"
                                   checked="@(theme == option)"
                                   @onchange="() => theme = option" />
                            <label class="form-check-label" for="@($"theme-{option}")">@option</label>
                        </div>
                    }
                </div>
            </div>

            @* Font Size *@
            <div class="card mb-4">
                <div class="card-body">
                    <h6 class="card-title">Font Size</h6>
                    @foreach (var option in new[] { "Small", "Medium", "Large" })
                    {
                        <div class="form-check mb-2">
                            <input class="form-check-input" type="radio" name="fontSize"
                                   id="@($"fs-{option}")"
                                   value="@option"
                                   checked="@(fontSize == option)"
                                   @onchange="() => fontSize = option" />
                            <label class="form-check-label" for="@($"fs-{option}")">@option</label>
                        </div>
                    }
                </div>
            </div>

            @* Language *@
            <div class="card mb-4">
                <div class="card-body">
                    <h6 class="card-title">Language</h6>
                    <select class="form-select" @bind="language">
                        <option value="en">English</option>
                        <option value="es">Español</option>
                        <option value="fr">Français</option>
                        <option value="de">Deutsch</option>
                        <option value="ja">日本語</option>
                        <option value="zh">中文</option>
                    </select>
                </div>
            </div>

            @* Compact Mode *@
            <div class="card mb-4">
                <div class="card-body">
                    <div class="form-check form-switch">
                        <input class="form-check-input" type="checkbox" id="compactMode" @bind="compactMode" />
                        <label class="form-check-label" for="compactMode">Compact Mode</label>
                        <div class="form-text">Reduce spacing and padding throughout the interface</div>
                    </div>
                </div>
            </div>

            <button class="btn btn-primary" @onclick="SaveAsync" disabled="@saving">
                @if (saving) { <span class="spinner-border spinner-border-sm me-1"></span> }
                Save
            </button>
        </div>

        @* Live Preview *@
        <div class="col-md-6">
            <div class="card">
                <div class="card-header">
                    <h6 class="mb-0">Preview</h6>
                </div>
                <div class="card-body preview-area @PreviewThemeClass"
                     style="@PreviewFontStyle @PreviewPaddingStyle">
                    <div class="preview-header mb-2" style="font-weight: 600;">
                        Dashboard
                    </div>
                    <div class="preview-nav mb-3">
                        <span class="preview-tab active">Home</span>
                        <span class="preview-tab">Settings</span>
                        <span class="preview-tab">Reports</span>
                    </div>
                    <div class="preview-card">
                        <div style="font-weight: 500;">Sample Card</div>
                        <p class="mb-1">This is how your content will look with the selected appearance settings.</p>
                        <button class="preview-btn">Action</button>
                    </div>
                    <div class="preview-meta mt-2">
                        Theme: @theme · Font: @fontSize · @GetLanguageName(language) · @(compactMode ? "Compact" : "Standard")
                    </div>
                </div>
            </div>
        </div>
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public AppearanceSettings Settings { get; set; } = default!;

    [Parameter, EditorRequired]
    public EventCallback<AppearanceSettings> OnSave { get; set; }

    private string theme = "Light";
    private string fontSize = "Medium";
    private string language = "en";
    private bool compactMode;
    private string? statusMessage;
    private bool isError;
    private bool saving;
    private bool initialized;

    protected override void OnParametersSet()
    {
        if (!initialized)
        {
            theme = Settings.Theme;
            fontSize = Settings.FontSize;
            language = Settings.Language;
            compactMode = Settings.CompactMode;
            initialized = true;
        }
    }

    private string PreviewThemeClass => theme switch
    {
        "Dark" => "preview-dark",
        "System" => "preview-system",
        _ => "preview-light"
    };

    private string PreviewFontStyle => fontSize switch
    {
        "Small" => "font-size: 0.8rem;",
        "Large" => "font-size: 1.15rem;",
        _ => "font-size: 0.95rem;"
    };

    private string PreviewPaddingStyle => compactMode
        ? "padding: 0.5rem;"
        : "padding: 1.25rem;";

    private static string GetLanguageName(string code) => code switch
    {
        "es" => "Español",
        "fr" => "Français",
        "de" => "Deutsch",
        "ja" => "日本語",
        "zh" => "中文",
        _ => "English"
    };

    private async Task SaveAsync()
    {
        saving = true;
        statusMessage = null;
        try
        {
            var updated = new AppearanceSettings(theme, fontSize, language, compactMode);
            await OnSave.InvokeAsync(updated);
            statusMessage = "Appearance settings saved!";
            isError = false;
        }
        catch
        {
            statusMessage = "Failed to save settings. Please try again.";
            isError = true;
        }
        finally
        {
            saving = false;
        }
    }
}
