    cursor: default;
}

.preview-tab.active {
    background: #0d6efd;
    color: #fff;
}

.preview-dark .preview-tab {
    background: rgba(255, 255, 255, 0.1);
}

.preview-dark .preview-tab.active {
    background: #4a9eff;
}

.preview-card {
    padding: 0.75rem;
    border-radius: 0.25rem;
