    padding: 0.2rem 0.75rem;
    border-radius: 0.25rem;
    border: 1px solid #0d6efd;
    background: #0d6efd;
    color: #fff;
    font-size: inherit;
    cursor: default;
}

.preview-meta {
    font-size: 0.8em;
    opacity: 0.6;
}
